92	// autoSelectSummaryProvider builds a provider for an auto-selected candidate
93	// (single-installed or non-interactive-first-of-many) and persists the choice
94	// so subsequent runs don't re-decide. Persistence failure is surfaced as a
95	// warning — not an error — because the selection is still usable in-process.
96	func autoSelectSummaryProvider(ctx context.Context, w io.Writer, name types.AgentName, reason string) (*checkpointSummaryProvider, error) {
97		logging.Info(ctx, reason, "provider", string(name))
98		provider, err := buildCheckpointSummaryProvider(name, "")
99		if err != nil {
100			return nil, err
101		}
102		flagFlipped, saveErr := persistSummaryProviderSelection(ctx, provider.Name, provider.Model)
103		if saveErr != nil {
104			logging.Warn(ctx, "failed to save summary provider selection, continuing without persistence",
105				"error", saveErr.Error())
106			fmt.Fprintf(w, "Warning: could not save provider selection: %v\nUse `entire configure --summarize-provider %s` to set it manually.\n", saveErr, provider.Name)
107		}
108		if flagFlipped {
109			fmt.Fprintln(w, externalAgentsAutoEnabledNotice)
110		}
111		return provider, nil
112	}
