114	func listEnabledSummaryProviders(_ context.Context) []checkpointSummaryProvider {
115		registered := listRegisteredAgents()
116		providers := make([]checkpointSummaryProvider, 0, len(registered))
117		for _, name := range registered {
118			ag, err := getSummaryAgent(name)
119			if err != nil {
120				continue
121			}
122			if _, ok := agent.AsTextGenerator(ag); !ok {
123				continue
124			}
125			// Check CLI binary on PATH for built-ins. External agents are already
126			// proven executable by discovery and are gated by text_generator.
127			if !isSummaryProviderAvailable(name, ag) {
128				continue
129			}
130			providers = append(providers, checkpointSummaryProvider{
131				Name:        name,
132				DisplayName: string(ag.Type()),
133			})
134		}
135		return providers
136	}
