227	// persistSummaryProviderSelection writes the chosen provider to
228	// settings.local.json. When the chosen provider is an external agent and
229	// external_agents is not yet enabled, it also flips that setting on so the
230	// plugin can actually run; in that case it returns flagFlipped=true so the
231	// caller can surface a one-time notice. The flag is written to local because
232	// the provider choice is already machine-specific (depends on $PATH).
233	func persistSummaryProviderSelection(ctx context.Context, provider types.AgentName, model string) (flagFlipped bool, err error) {
234		targetFileAbs, err := paths.AbsPath(ctx, settings.EntireSettingsLocalFile)
235		if err != nil {
236			targetFileAbs = settings.EntireSettingsLocalFile
237		}
238	
239		s, err := loadSummarySettingsFromFile(targetFileAbs)
240		if err != nil {
241			return false, fmt.Errorf("loading settings for update: %w", err)
242		}
243		if s.SummaryGeneration == nil {
244			s.SummaryGeneration = &settings.SummaryGenerationSettings{}
245		}
246		s.SummaryGeneration.SetProvider(string(provider), model)
247	
248		if ag, getErr := getSummaryAgent(provider); getErr == nil && external.IsExternal(ag) && !s.ExternalAgents {
249			s.ExternalAgents = true
250			flagFlipped = true
251		}
252	
253		if err := saveLocalSummarySettings(ctx, s); err != nil {
254			return false, fmt.Errorf("saving summary provider selection: %w", err)
255		}
256		return flagFlipped, nil
257	}
