// fakeGenerator is a programmable TextGenerator. Each Call returns the next
// scripted response or runs the next scripted func.
type fakeGenerator struct {
	mu        sync.Mutex
	responses []func(prompt string) (string, error)
	prompts   []string
}

func (f *fakeGenerator) GenerateText(_ context.Context, prompt, _ string) (string, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.prompts = append(f.prompts, prompt)
	if len(f.responses) == 0 {
		return "", errors.New("fake: out of scripted responses")
	}
	resp := f.responses[0]
	f.responses = f.responses[1:]
	return resp(prompt)
}

func (f *fakeGenerator) prompt(i int) string {
	f.mu.Lock()
	defer f.mu.Unlock()
	if i >= len(f.prompts) {
		return ""
	}
	return f.prompts[i]
}

type sample struct {
	Tag string `json:"tag"`
}

var sampleValidator = JSONValidator(
	func() *sample { return &sample{} },
	func(s *sample) error {
