)

// seedExplainCache populates a minimal understand cache so explain has
// something to read. Layout: a file node, a contained symbol, and one
// checkpoint touched_in for the file.
func seedExplainCache(t *testing.T, dir string) {
	t.Helper()
	store := graph.NewStore(dir)

	structural := &graph.Slice{
		Nodes: []graph.Node{
			{ID: "repo:.", Type: graph.NodeRepo, Name: "."},
			{ID: "file:cmd/main.go", Type: graph.NodeFile, Name: "main.go", Path: "cmd/main.go", Language: "go"},
			{ID: "sym:cmd/main.go:main", Type: graph.NodeSymbol, SymbolKind: graph.SymbolFunction, Name: "main", Path: "cmd/main.go", Language: "go", LineStart: 5, LineEnd: 7},
		},
		Edges: []graph.Edge{
			{ID: "e:contains:repo:file", From: "repo:.", To: "file:cmd/main.go", Type: graph.EdgeContains},
			{ID: "e:contains:file:sym", From: "file:cmd/main.go", To: "sym:cmd/main.go:main", Type: graph.EdgeContains},
		},
	}
	history := &graph.Slice{
		Nodes: []graph.Node{
			{ID: "cp:abc123def456", Type: graph.NodeCheckpoint, Name: "abc123def456", Attrs: map[string]any{
				"created_at": time.Date(2026, 5, 5, 12, 0, 0, 0, time.UTC).Format(time.RFC3339),
				"agent":      "claude-code",
			}},
		},
		Edges: []graph.Edge{
			{ID: "e:touched:cp->file", From: "cp:abc123def456", To: "file:cmd/main.go", Type: graph.EdgeTouchedIn, Scope: graph.ScopeFileOwner},
		},
	}

	if err := store.WriteStructural(structural); err != nil {
		t.Fatalf("WriteStructural: %v", err)
	}
	if err := store.WriteHistory(history); err != nil {
		t.Fatalf("WriteHistory: %v", err)
	}
	if err := store.WriteManifest(&graph.Manifest{
		BuildID:          "test",
		BuiltAt:          time.Now().UTC(),
		StructuralStatus: "ok",
		HistoryStatus:    "ok",
		SemanticStatus:   graph.SemanticSkipped,
		NodeCount:        4,
		EdgeCount:        3,
	}); err != nil {
		t.Fatalf("WriteManifest: %v", err)
	}
}

func TestUnderstandExplain_NoCache(t *testing.T) {
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	t.Chdir(dir)
	paths.ClearWorktreeRootCache()

	var buf bytes.Buffer
	if err := runUnderstandExplain(context.Background(), &buf, "main.go", false); err != nil {
		t.Fatalf("runUnderstandExplain: %v", err)
