	"github.com/spf13/cobra"
)

// newUnderstandExamplesCmd builds `entire understand examples <pattern>`.
//
// The pattern is treated as untrusted data — it is never injected into a
// model prompt. The deterministic match path uses lexical substring search
// over node names and paths, scored by recency × match strength. Semantic
// pattern-graph traversal is wired in but disabled until build runs actual
// synthesis (deterministic-only for v1).
func newUnderstandExamplesCmd() *cobra.Command {
	var jsonOut bool
	var maxResults int

	cmd := &cobra.Command{
		Use:   "examples <pattern>",
		Short: "Find structurally similar examples for a pattern",
		Long: `Search node names and paths for the given pattern and rank matches by
recency and match strength. Output includes a "why this matched" reason for
each example.

Examples:
  entire understand examples NewStore
  entire understand examples "rate limiter"`,
		Args: cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			return runUnderstandExamples(cmd.Context(), cmd.OutOrStdout(), args[0], jsonOut, maxResults)
		},
	}
	cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit JSON instead of markdown")
	cmd.Flags().IntVar(&maxResults, "max", 20, "Maximum number of results to return")
	return cmd
}

type exampleHit struct {
	NodeID    string  `json:"node_id"`
	Path      string  `json:"path,omitempty"`
	Type      string  `json:"type"`
	Score     float64 `json:"score"`
	Reason    string  `json:"reason"`
	LastAt    string  `json:"last_at,omitempty"`
	LastCpID  string  `json:"last_cp,omitempty"`
}

type examplesReport struct {
	Pattern string       `json:"pattern"`
	Hits    []exampleHit `json:"hits"`
}

func runUnderstandExamples(ctx context.Context, w io.Writer, pattern string, jsonOut bool, maxResults int) error {
	q, err := loadQueryEnv(ctx)
	if err != nil {
		if errors.Is(err, errNoUnderstandCache) {
			fmt.Fprintln(w, err.Error())
			return nil
		}
		return err
	}

	pattern = strings.TrimSpace(pattern)
	report := examplesReport{Pattern: pattern}
	if pattern == "" {
		return emitExamples(w, report, jsonOut)
	}

	lower := strings.ToLower(pattern)

	for i := range q.fused.Nodes {
		n := &q.fused.Nodes[i]
		if n.Type != graph.NodeFile && n.Type != graph.NodeSymbol {
			continue
		}
		score, reason := scoreExampleMatch(n, lower)
		if score <= 0 {
			continue
		}
		hit := exampleHit{
			NodeID: n.ID,
			Path:   n.Path,
			Type:   string(n.Type),
			Score:  score,
			Reason: reason,
		}
		if cp := q.recentCheckpoint(n.ID); cp != nil {
			hit.LastCpID = cp.Name
			if at, ok := cp.Attrs["created_at"].(string); ok {
				hit.LastAt = at
			}
		}
		report.Hits = append(report.Hits, hit)
	}

	sort.Slice(report.Hits, func(i, j int) bool {
		if report.Hits[i].Score != report.Hits[j].Score {
			return report.Hits[i].Score > report.Hits[j].Score
		}
		// Tiebreak: most-recently touched first.
		return report.Hits[i].LastAt > report.Hits[j].LastAt
	})
	if maxResults > 0 && len(report.Hits) > maxResults {
		report.Hits = report.Hits[:maxResults]
	}
	return emitExamples(w, report, jsonOut)
}

// scoreExampleMatch returns a non-negative score (higher = better match) and a
// short human-readable reason. Symbol-name exact matches outrank file-name
// substring matches outrank path substring matches.
func scoreExampleMatch(n *graph.Node, lowerPattern string) (float64, string) {
	lowerName := strings.ToLower(n.Name)
	lowerPath := strings.ToLower(n.Path)

	switch {
	case n.Type == graph.NodeSymbol && lowerName == lowerPattern:
		return 4.0, "symbol name exactly matches"
	case n.Type == graph.NodeSymbol && strings.Contains(lowerName, lowerPattern):
		return 3.0, "symbol name contains pattern"
	case lowerName == lowerPattern:
		return 2.5, "node name exactly matches"
	case strings.Contains(lowerName, lowerPattern):
		return 2.0, "node name contains pattern"
	case strings.Contains(lowerPath, lowerPattern):
		return 1.0, "path contains pattern"
	default:
		return 0, ""
	}
}

func emitExamples(w io.Writer, r examplesReport, jsonOut bool) error {
	if jsonOut {
		data, err := jsonutil.MarshalIndentWithNewline(r, "", "  ")
		if err != nil {
			return fmt.Errorf("marshal examples: %w", err)
		}
		if _, err := w.Write(data); err != nil {
			return fmt.Errorf("write examples JSON: %w", err)
		}
		return nil
	}
	if r.Pattern == "" {
		fmt.Fprintln(w, "_Empty pattern; nothing to match._")
		return nil
	}
	if len(r.Hits) == 0 {
		fmt.Fprintf(w, "_No matches for pattern %q._\n", r.Pattern)
		return nil
	}
	fmt.Fprintf(w, "# Examples for `%s`\n\n", r.Pattern)
	for _, h := range r.Hits {
		path := h.Path
		if path == "" {
			path = h.NodeID
		}
		fmt.Fprintf(w, "- **%s** _(%s)_ — %s", path, h.Type, h.Reason)
		if h.LastCpID != "" {
			fmt.Fprintf(w, "; last in `%s`", h.LastCpID)
			if h.LastAt != "" {
				fmt.Fprintf(w, " at %s", h.LastAt)
			}
		}
		fmt.Fprintln(w)
	}
	return nil
}

