// Package dashboard exposes a loopback-only HTTP server for the
// `entire understand dashboard` command.
//
// Security posture (per spec):
//
//   - bind to 127.0.0.1 only — never 0.0.0.0
//   - generate a fresh random bearer token per launch
//   - require the token on every request via the Authorization header (never
//     query string, so the token cannot leak into browser history, screenshots,
//     or copied URLs)
//   - read-only endpoints, never bulk-expose transcripts
//   - prompt/transcript content is fetched on demand by checkpoint ID and
//     gated by the same per-launch token
//
// The HTML shell is bootstrapped with the token via a server-injected
// <script>window.__entireUnderstandToken=...</script> tag so the JS never
// needs to read it from a URL or a cookie.
package dashboard

import (
	"context"
	"crypto/rand"
	_ "embed"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"html"
	"net"
	"net/http"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/understand/graph"
)

//go:embed assets/index.html
var indexHTML string

// Server is the loopback dashboard. Construct via New and start with Start.
type Server struct {
	store     *graph.Store
	listener  net.Listener
	server    *http.Server
	token     string
	addr      string
	startedAt time.Time
}

// New builds an unstarted server bound to the given store.
func New(store *graph.Store) (*Server, error) {
	if store == nil {
		return nil, errors.New("dashboard: nil store")
	}
	tok, err := mintToken()
	if err != nil {
		return nil, err
	}
	return &Server{store: store, token: tok}, nil
}

// Start binds the listener on 127.0.0.1:<port>, registers handlers, and runs
// the server in the background. Returns the chosen URL (with /).
func (s *Server) Start(_ context.Context) (string, error) {
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		return "", fmt.Errorf("dashboard: listen: %w", err)
	}
	s.listener = ln
	s.addr = ln.Addr().String()

	mux := http.NewServeMux()
	s.RegisterHandlers(mux)

	s.server = &http.Server{
		Handler:           mux,
		ReadHeaderTimeout: 5 * time.Second,
	}
	s.startedAt = time.Now()
	go func() {
		_ = s.server.Serve(ln)
	}()

	return "http://" + s.addr + "/", nil
}

// Stop shuts the server down with a 2-second drain.
func (s *Server) Stop() error {
	if s.server == nil {
		return nil
	}
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()
	if err := s.server.Shutdown(ctx); err != nil {
		return fmt.Errorf("dashboard: shutdown: %w", err)
	}
	return nil
}

// Token returns the per-launch bearer token. Surfaced for the CLI command's
// banner and for tests.
func (s *Server) Token() string { return s.token }

// Addr returns the bound 127.0.0.1:<port> string. Empty until Start is called.
func (s *Server) Addr() string { return s.addr }

// RegisterHandlers wires the read-only endpoints onto a mux. Exposed so tests
// can drive the server with httptest.NewRecorder + http.Handler directly.
func (s *Server) RegisterHandlers(mux *http.ServeMux) {
	mux.HandleFunc("/", s.serveIndex)
	mux.HandleFunc("/api/manifest", s.requireToken(s.handleManifest))
	mux.HandleFunc("/api/graph", s.requireToken(s.handleGraph))
	mux.HandleFunc("/api/timeline", s.requireToken(s.handleTimeline))
	mux.HandleFunc("/api/hotspots", s.requireToken(s.handleHotspots))
	mux.HandleFunc("/api/checkpoint/", s.requireToken(s.handleCheckpointStub))
}

// requireToken wraps a handler so each request must present the per-launch
// bearer token. Bypasses the index page so the bootstrap HTML can load.
func (s *Server) requireToken(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet {
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
			return
		}
		auth := r.Header.Get("Authorization")
		if !strings.HasPrefix(auth, "Bearer ") {
			http.Error(w, "missing bearer token", http.StatusUnauthorized)
			return
		}
		got := strings.TrimSpace(strings.TrimPrefix(auth, "Bearer "))
		if got != s.token {
			http.Error(w, "bad token", http.StatusUnauthorized)
			return
		}
		next(w, r)
	}
}

func (s *Server) serveIndex(w http.ResponseWriter, r *http.Request) {
	if r.URL.Path != "/" {
		http.NotFound(w, r)
		return
	}
	// Inject the per-launch token into a script tag *before* the embedded
	// HTML. The token is rendered through html.EscapeString defensively even
	// though it's hex; this also documents the framing rule for future
	// maintainers (don't drop user-controlled values into bootstrap).
	bootstrap := "<script>window.__entireUnderstandToken=" +
		"\"" + html.EscapeString(s.token) + "\";</script>\n"
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("X-Content-Type-Options", "nosniff")
	w.Header().Set("Cache-Control", "no-store")
	_, _ = w.Write([]byte(bootstrap))
	_, _ = w.Write([]byte(indexHTML))
}

func (s *Server) handleManifest(w http.ResponseWriter, _ *http.Request) {
	m, err := s.store.ReadManifest()
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	writeJSON(w, m)
}

func (s *Server) handleGraph(w http.ResponseWriter, _ *http.Request) {
	fused, err := s.store.FusedGraph()
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	writeJSON(w, fused)
}

func (s *Server) handleTimeline(w http.ResponseWriter, _ *http.Request) {
	tl, err := s.store.ReadTimeline()
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	writeJSON(w, tl)
}

// HotspotShape is the JSON shape returned by /api/hotspots. Mirrors the
// hotspot rows produced by `entire understand hotspots` so the dashboard
// and CLI agree on the contract.
type HotspotShape struct {
	NodeID          string  `json:"node_id"`
	Path            string  `json:"path"`
	CheckpointCount int     `json:"checkpoint_count"`
	DistinctAgents  int     `json:"distinct_agents"`
	Score           float64 `json:"score"`
}

func (s *Server) handleHotspots(w http.ResponseWriter, _ *http.Request) {
	fused, err := s.store.FusedGraph()
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	rows := computeHotspots(fused)
	writeJSON(w, map[string]any{"hotspots": rows})
}

// handleCheckpointStub returns a stable 404 for now. The intent — per the
// spec — is to fetch prompt/transcript content on demand by checkpoint ID
// only when the per-launch bearer token is present. The actual loader
// requires the agent transcript path, which is out of scope for the v1
// dashboard. Keeping the route registered (and gated by requireToken)
// documents the contract and prevents accidental bulk exposure later.
func (s *Server) handleCheckpointStub(w http.ResponseWriter, _ *http.Request) {
	http.Error(w, "checkpoint detail not yet exposed in v1; use `entire understand explain` from the CLI", http.StatusNotFound)
}

// computeHotspots builds the same per-file score the CLI hotspots command
// produces, in the same order. Lives here (rather than in package cli) so
// the dashboard handler stays self-contained and testable without importing
// cli into a server-side package.
func computeHotspots(fused *graph.Slice) []HotspotShape {
	byID := make(map[string]*graph.Node, len(fused.Nodes))
	touchedCps := map[string][]string{}
	for i := range fused.Nodes {
		byID[fused.Nodes[i].ID] = &fused.Nodes[i]
	}
	for _, e := range fused.Edges {
		if e.Type == graph.EdgeTouchedIn {
			touchedCps[e.To] = append(touchedCps[e.To], e.From)
		}
	}
	out := []HotspotShape{}
	for fileID, cps := range touchedCps {
		n := byID[fileID]
		if n == nil || n.Type != graph.NodeFile {
			continue
		}
		agents := map[string]struct{}{}
		for _, cpID := range cps {
			cp := byID[cpID]
			if cp == nil {
				continue
			}
			a, _ := cp.Attrs["agent"].(string)
			if a != "" {
				agents[a] = struct{}{}
			}
		}
		out = append(out, HotspotShape{
			NodeID:          fileID,
			Path:            n.Path,
			CheckpointCount: len(cps),
			DistinctAgents:  len(agents),
			Score:           float64(len(cps)) + 0.5*float64(len(agents)),
		})
	}
	// Highest score first; tiebreak by path for determinism.
	for i := 0; i < len(out); i++ {
		for j := i + 1; j < len(out); j++ {
			if out[j].Score > out[i].Score || (out[j].Score == out[i].Score && out[j].Path < out[i].Path) {
				out[i], out[j] = out[j], out[i]
			}
		}
	}
	return out
}

func writeJSON(w http.ResponseWriter, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.Header().Set("X-Content-Type-Options", "nosniff")
	w.Header().Set("Cache-Control", "no-store")
	enc := json.NewEncoder(w)
	enc.SetEscapeHTML(false)
	_ = enc.Encode(v)
}

func mintToken() (string, error) {
	var b [16]byte
	if _, err := rand.Read(b[:]); err != nil {
		return "", fmt.Errorf("dashboard: random token: %w", err)
	}
	return hex.EncodeToString(b[:]), nil
}

package cli

import (
	"context"
	"errors"
	"fmt"
	"io"
	"os/exec"
	"runtime"

	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/understand/dashboard"
	"github.com/entireio/cli/cmd/entire/cli/understand/graph"
	"github.com/spf13/cobra"
)

// newUnderstandDashboardCmd builds `entire understand dashboard`.
//
// Server is loopback-only with a per-launch bearer token. Token is rendered
// into the bootstrap HTML via a server-injected script tag — never via a URL
// or query string — so it can't leak into browser history or screenshots.
//
// --print emits the URL + token to stdout instead of starting the browser
// and is the form tests and scripted callers should use.
//
// --replay is accepted for API compatibility with the `replay` command; for
// v1 it is a thin alias that just sets a query-string-free fragment hash so
// the SPA can default to a replay-mode view.
func newUnderstandDashboardCmd() *cobra.Command {
	var openBrowser bool
	var replay bool
	var printOnly bool

	cmd := &cobra.Command{
		Use:   "dashboard",
		Short: "Launch the loopback dashboard for the understand graph",
		Long: `Start a 127.0.0.1-only HTTP server backed by the local understand cache.

Each launch mints a fresh random bearer token. The token is required on
every API call via the Authorization header — never in the URL — so it
cannot leak into browser history, screenshots, or copied links.

Endpoints:
  /                  HTML shell (bootstraps the token into window state)
  /api/manifest      Build manifest
  /api/graph         Fused graph (read-only, no transcript bodies)
  /api/timeline      Replay events
  /api/hotspots      Per-file score table
  /api/checkpoint/<id>
                     Reserved for on-demand transcript lookup; v1 returns 404
                     to prevent bulk exposure.`,
		RunE: func(cmd *cobra.Command, _ []string) error {
			return runUnderstandDashboard(cmd.Context(), cmd.OutOrStdout(), dashboardOptions{
				Open:    openBrowser,
				Replay:  replay,
				PrintOnly: printOnly,
			})
		},
	}
	cmd.Flags().BoolVar(&openBrowser, "open", false, "Open the URL in the default browser after launch")
	cmd.Flags().BoolVar(&replay, "replay", false, "Default the dashboard view to replay/timeline mode")
	cmd.Flags().BoolVar(&printOnly, "print", false, "Print the URL + token and exit instead of running the server")
	return cmd
}

type dashboardOptions struct {
	Open      bool
	Replay    bool
	PrintOnly bool
}

func runUnderstandDashboard(ctx context.Context, w io.Writer, opts dashboardOptions) error {
	root, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return fmt.Errorf("resolve repo root: %w", err)
	}
	store := graph.NewStore(root)
	if !store.Exists() {
		return errors.New("no understand cache yet — run `entire understand build`")
	}

	srv, err := dashboard.New(store)
	if err != nil {
		return fmt.Errorf("dashboard: %w", err)
	}
	if opts.PrintOnly {
		// Build a printable line that includes the token but does NOT actually
		// start the listener. Useful for tests and for users who want to
		// drive the API from curl without opening a browser tab.
		fmt.Fprintf(w, "would-launch: token=%s (run without --print to bind)\n", srv.Token())
		return nil
	}

	url, err := srv.Start(ctx)
	if err != nil {
		return fmt.Errorf("start dashboard: %w", err)
	}
	defer func() { _ = srv.Stop() }()

	suffix := ""
	if opts.Replay {
		suffix = "#replay"
	}
	fullURL := url + suffix
	fmt.Fprintf(w, "dashboard: %s\n", fullURL)
	fmt.Fprintf(w, "  bearer token: %s (use Authorization: Bearer ...)\n", srv.Token())
	if opts.Open {
		if err := openBrowserCommand(fullURL); err != nil {
			fmt.Fprintf(w, "  (couldn't open browser automatically: %s)\n", err.Error())
		}
	}
	fmt.Fprintln(w, "  press Ctrl-C to stop the server.")

	<-ctx.Done()
	return nil
}

// openBrowserCommand uses the platform's default URL opener. We do not pass
// the token to the OS opener — it is already in the page bootstrap.
func openBrowserCommand(url string) error {
	var bin string
	var args []string
	switch runtime.GOOS {
	case "darwin":
		bin = "open"
		args = []string{url}
	case "windows":
		bin = "rundll32"
		args = []string{"url.dll,FileProtocolHandler", url}
	default:
		bin = "xdg-open"
		args = []string{url}
	}
	if _, err := exec.LookPath(bin); err != nil {
		return fmt.Errorf("no URL opener on PATH (%s): %w", bin, err)
	}
	cmd := exec.Command(bin, args...) //nolint:gosec // bin/args resolved against an allowlist
	if err := cmd.Start(); err != nil {
		return fmt.Errorf("open browser: %w", err)
	}
	return nil
}

package cli

import (
	"context"
	"errors"
	"fmt"
	"io"
	"sort"

	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/understand/graph"
	"github.com/spf13/cobra"
)

// newUnderstandReplayCmd builds `entire understand replay`.
//
// CLI replay is a textual scrubber over the persisted timeline. The dashboard
// command provides a richer browser-side view of the same data; replay's
// CLI form keeps the read API symmetric and exists so users can pipe the
// chronological event stream into shell tools without launching a browser.
func newUnderstandReplayCmd() *cobra.Command {
	var (
		from    string
		to      string
		jsonOut bool
		limit   int
	)

	cmd := &cobra.Command{
		Use:   "replay",
		Short: "Replay the codebase timeline (text or JSON)",
		Long: `Render the persisted timeline of checkpoints in chronological order.

Filters:
  --from <ts|cp>     Start timestamp (RFC3339) or checkpoint id
  --to   <ts|cp>     End timestamp or checkpoint id
  --limit <n>        Cap the rendered events
  --json             Emit the filtered events as JSON

Examples:
  entire understand replay --from 2026-04-01T00:00:00Z
  entire understand replay --from abc123 --to def456 --json`,
		RunE: func(cmd *cobra.Command, _ []string) error {
			return runUnderstandReplay(cmd.Context(), cmd.OutOrStdout(), replayOptions{
				From:    from,
				To:      to,
				Limit:   limit,
				JSONOut: jsonOut,
			})
		},
	}
	cmd.Flags().StringVar(&from, "from", "", "Start timestamp (RFC3339) or checkpoint id")
	cmd.Flags().StringVar(&to, "to", "", "End timestamp or checkpoint id")
	cmd.Flags().IntVar(&limit, "limit", 0, "Maximum number of events to render (0 = all)")
	cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit JSON instead of text")
	return cmd
}

type replayOptions struct {
	From    string
	To      string
	Limit   int
	JSONOut bool
}

type replayReport struct {
	From   string                `json:"from,omitempty"`
	To     string                `json:"to,omitempty"`
	Events []graph.TimelineEvent `json:"events"`
}

func runUnderstandReplay(ctx context.Context, w io.Writer, opts replayOptions) error {
	root, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return fmt.Errorf("resolve repo root: %w", err)
	}
	store := graph.NewStore(root)
	if !store.Exists() {
		return errors.New("no understand cache yet — run `entire understand build`")
	}
	tl, err := store.ReadTimeline()
	if err != nil {
		return fmt.Errorf("read timeline: %w", err)
	}

	events := append([]graph.TimelineEvent{}, tl.Events...)
	sort.SliceStable(events, func(i, j int) bool { return events[i].At < events[j].At })

	events = filterByBounds(events, opts.From, opts.To)
	if opts.Limit > 0 && len(events) > opts.Limit {
		events = events[:opts.Limit]
	}

	report := replayReport{From: opts.From, To: opts.To, Events: events}
	if opts.JSONOut {
		data, err := jsonutil.MarshalIndentWithNewline(report, "", "  ")
		if err != nil {
			return fmt.Errorf("marshal replay: %w", err)
		}
		if _, err := w.Write(data); err != nil {
			return fmt.Errorf("write replay JSON: %w", err)
		}
		return nil
	}
	if len(events) == 0 {
		fmt.Fprintln(w, "_No events in the requested range._")
		return nil
	}
	fmt.Fprintln(w, "# Replay")
	for _, e := range events {
		fmt.Fprintf(w, "- %s `%s`", e.At, e.CheckpointID)
		if e.SessionID != "" {
			fmt.Fprintf(w, " session=%s", e.SessionID)
		}
		if len(e.NodeIDs) > 0 {
			fmt.Fprintf(w, " files=%d", len(e.NodeIDs))
		}
		fmt.Fprintln(w)
	}
	return nil
}

// filterByBounds keeps events whose `At` (or CheckpointID) sits within the
// inclusive [from, to] window. Each side accepts a timestamp string or a
// checkpoint id; comparison falls back to lexical order on `At` for
// timestamps and exact match on CheckpointID otherwise. This is intentionally
// simple — a real implementation would parse RFC3339 explicitly.
func filterByBounds(events []graph.TimelineEvent, from, to string) []graph.TimelineEvent {
	if from == "" && to == "" {
		return events
	}
	out := events[:0]
	for _, e := range events {
		if from != "" && !boundMatches(e, from, "from") {
			continue
		}
		if to != "" && !boundMatches(e, to, "to") {
			continue
		}
		out = append(out, e)
	}
	return out
}

func boundMatches(e graph.TimelineEvent, bound, side string) bool {
	if e.CheckpointID == bound {
		return true
	}
	switch side {
	case "from":
		return e.At >= bound
	case "to":
		return e.At <= bound
	default:
		return true
	}
}

package dashboard

import (
	"encoding/json"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/understand/graph"
)

// makeStore returns a populated graph.Store rooted in t.TempDir() so the
// server has artifacts to read.
func makeStore(t *testing.T) *graph.Store {
	t.Helper()
	dir := t.TempDir()
	store := graph.NewStore(dir)
	if err := store.WriteManifest(&graph.Manifest{
		BuildID:          "test-build",
		BuiltAt:          time.Date(2026, 5, 5, 0, 0, 0, 0, time.UTC),
		StructuralStatus: "ok",
		HistoryStatus:    "ok",
		SemanticStatus:   graph.SemanticSkipped,
		NodeCount:        2,
		EdgeCount:        1,
	}); err != nil {
		t.Fatalf("WriteManifest: %v", err)
	}
	if err := store.WriteStructural(&graph.Slice{
		Nodes: []graph.Node{
			{ID: "file:main.go", Type: graph.NodeFile, Name: "main.go", Path: "main.go"},
		},
	}); err != nil {
		t.Fatalf("WriteStructural: %v", err)
	}
	if err := store.WriteHistory(&graph.Slice{
		Nodes: []graph.Node{
			{ID: "cp:abc", Type: graph.NodeCheckpoint, Name: "abc", Attrs: map[string]any{"agent": "claude-code"}},
		},
		Edges: []graph.Edge{
			{ID: "h1", From: "cp:abc", To: "file:main.go", Type: graph.EdgeTouchedIn, Scope: graph.ScopeFileOwner},
		},
	}); err != nil {
		t.Fatalf("WriteHistory: %v", err)
	}
	if err := store.WriteTimeline(&graph.Timeline{
		Events: []graph.TimelineEvent{
			{At: "2026-05-05T00:00:00Z", CheckpointID: "abc", Kind: "checkpoint", NodeIDs: []string{"file:main.go"}},
		},
	}); err != nil {
		t.Fatalf("WriteTimeline: %v", err)
	}
	return store
}

func newHandler(t *testing.T) (*Server, http.Handler) {
	t.Helper()
	store := makeStore(t)
	srv, err := New(store)
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	mux := http.NewServeMux()
	srv.RegisterHandlers(mux)
